import React from "react";
import { useTranslation } from "gatsby-plugin-react-i18next";
import Link from "./AppLink";
import data from "../data/data.json";
import type { Company } from "../interfaces";
import {
  getCaseStudyPrimaryServicePath,
  getServiceKeyFromPath,
} from "../utils/journeyLinks";
import { buildContactIntentPath } from "../utils/cta";

const info: Company = data[0];

const normalizeList = (input: unknown): string[] => {
  if (!Array.isArray(input)) return [];
  return input
    .map((item) => {
      if (typeof item === "string") return item;
      if (item && typeof item === "object" && "item" in item) {
        return String((item as { item?: string }).item || "").trim();
      }
      return "";
    })
    .filter(Boolean);
};

type MetricItem = {
  label: string;
  value: string;
  note?: string;
};

const normalizeMetrics = (input: unknown): MetricItem[] => {
  if (!Array.isArray(input)) return [];

  return input
    .map((item) => {
      if (!item || typeof item !== "object") return null;

      const metric = item as {
        label?: string;
        value?: string;
        note?: string;
      };

      const label = String(metric.label || "").trim();
      const value = String(metric.value || "").trim();
      const note = String(metric.note || "").trim();

      if (!label || !value) return null;

      return { label, value, ...(note ? { note } : {}) };
    })
    .filter((item): item is MetricItem => Boolean(item));
};

function slugify(input: string) {
  return input
    .toLowerCase()
    .trim()
    .replace(/&/g, "and")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

type Props = {
  slug: string;
};

const CaseStudyPreview: React.FC<Props> = ({ slug }) => {
  const { t } = useTranslation();

  const baseKey = `caseStudies.items.${slug}`;
  const name = t(`${baseKey}.name`, { defaultValue: "" }) as string;
  if (!name) return null;

  const summary = t(`${baseKey}.summary`, { defaultValue: "" }) as string;
  const market = t(`${baseKey}.market`, { defaultValue: "" }) as string;
  const audience = t(`${baseKey}.audience`, { defaultValue: "" }) as string;
  const projectType = t(`${baseKey}.projectType`, {
    defaultValue: "",
  }) as string;
  const projectWindow = t(`${baseKey}.projectWindow`, {
    defaultValue: "",
  }) as string;
  const scope = t(`${baseKey}.scope`, {
    defaultValue: "",
  }) as string;
  const challenge = normalizeList(
    t(`${baseKey}.challenge`, { returnObjects: true, defaultValue: [] })
  );
  const delivered = normalizeList(
    t(`${baseKey}.delivered`, { returnObjects: true, defaultValue: [] })
  );
  const stack = normalizeList(
    t(`${baseKey}.stack`, { returnObjects: true, defaultValue: [] })
  );
  const results = normalizeList(
    t(`${baseKey}.results`, { returnObjects: true, defaultValue: [] })
  );
  const focus = normalizeList(
    t(`${baseKey}.focus`, { returnObjects: true, defaultValue: [] })
  );
  const metrics = normalizeMetrics(
    t(`${baseKey}.metrics`, { returnObjects: true, defaultValue: [] })
  );
  const primaryServicePath = getCaseStudyPrimaryServicePath(slug);
  const primaryServiceKey = getServiceKeyFromPath(primaryServicePath);
  const primaryServiceLabel = primaryServiceKey
    ? (t(`menu.services.${primaryServiceKey}.nav`, { ns: "index" }) as string)
    : (t("menu.servicesHub.nav", { ns: "index" }) as string);
  const overviewItems = [
    {
      label: t("caseStudies.overviewLabels.market") as string,
      value: market,
    },
    {
      label: t("caseStudies.overviewLabels.audience") as string,
      value: audience,
    },
    {
      label: t("caseStudies.overviewLabels.projectType") as string,
      value: projectType,
    },
  ].filter((item) => item.value);
  const evidenceItems = [
    {
      label: t("caseStudies.evidenceLabels.projectWindow") as string,
      value: projectWindow,
    },
    {
      label: t("caseStudies.evidenceLabels.scope") as string,
      value: scope,
    },
  ].filter((item) => item.value);
  const liveProjectUrl = (info?.homePage?.portfolio || []).find(
    (project) => slugify(project.title) === slug
  )?.link;

  return (
    <div>
      {/* HERO */}
      <section className="pt-10 pb-6 sm:pt-14 sm:pb-10">
        <div className={styles.container}>
          <div className="text-center">
            <h1 className="text-3xl sm:text-5xl poppins-bold text-light mx-auto max-w-4xl">
              {t("caseStudies.hero.title", { name })}
            </h1>

            {summary ? (
              <p className="mt-4 text-lg sm:text-2xl poppins-regular text-light/90 mx-auto max-w-4xl">
                {summary}
              </p>
            ) : null}

            <div className="mx-auto mt-8 flex flex-col sm:flex-row items-center justify-center gap-3">
              {liveProjectUrl ? (
                <a
                  href={liveProjectUrl}
                  target="_blank"
                  rel="noreferrer"
                  className="rounded-full border border-white/20 bg-white/10 px-5 py-2.5 text-light text-center"
                >
                  {t("portfolio.buttons.visit")}
                </a>
              ) : null}

              {primaryServicePath ? (
                <Link
                  to={primaryServicePath}
                  className="rounded-full bg-secondary px-5 py-2.5 text-light text-center"
                >
                  {t("caseStudies.cta.relatedService", {
                    service: primaryServiceLabel,
                  })}
                </Link>
              ) : null}

              <Link
                to={buildContactIntentPath("similarProject")}
                className="rounded-full bg-purplesemilight px-5 py-2.5 text-dark font-semibold text-center"
              >
                {t("caseStudies.cta.contactSimilarProject")}
              </Link>
            </div>
          </div>
        </div>
      </section>

      {/* DETAILS */}
      <section className="py-8 sm:py-12">
        <div className={styles.container}>
          {overviewItems.length || focus.length ? (
            <article className={styles.card}>
              <h2 className={styles.cardTitle}>{t("caseStudies.sections.overview")}</h2>

              {overviewItems.length ? (
                <dl className="mt-4 grid grid-cols-1 gap-3 sm:grid-cols-3">
                  {overviewItems.map((item) => (
                    <div
                      key={item.label}
                      className="rounded-xl border border-white/10 bg-white/5 p-4"
                    >
                      <dt className="text-[11px] uppercase tracking-[0.16em] text-light/50">
                        {item.label}
                      </dt>
                      <dd className="mt-2 text-sm sm:text-base text-light/90">
                        {item.value}
                      </dd>
                    </div>
                  ))}
                </dl>
              ) : null}

              {focus.length ? (
                <div className="mt-6">
                  <h3 className="text-sm font-semibold uppercase tracking-[0.16em] text-light/60">
                    {t("caseStudies.sections.focus")}
                  </h3>
                  <ul className="mt-3 flex flex-wrap gap-2">
                    {focus.map((item, idx) => (
                      <li key={`focus-${idx}`} className={styles.badge}>
                        {item}
                      </li>
                    ))}
                  </ul>
                </div>
              ) : null}
            </article>
          ) : null}

          {evidenceItems.length || metrics.length ? (
            <article className={`${styles.card} mt-4`}>
              <h2 className={styles.cardTitle}>{t("caseStudies.sections.evidence")}</h2>

              {evidenceItems.length ? (
                <dl className="mt-4 grid grid-cols-1 gap-3 sm:grid-cols-2">
                  {evidenceItems.map((item) => (
                    <div
                      key={item.label}
                      className="rounded-xl border border-white/10 bg-white/5 p-4"
                    >
                      <dt className="text-[11px] uppercase tracking-[0.16em] text-light/50">
                        {item.label}
                      </dt>
                      <dd className="mt-2 text-sm sm:text-base text-light/90">
                        {item.value}
                      </dd>
                    </div>
                  ))}
                </dl>
              ) : null}

              {metrics.length ? (
                <div className="mt-6 grid grid-cols-1 gap-3 lg:grid-cols-3">
                  {metrics.map((metric) => (
                    <div
                      key={`${metric.label}-${metric.value}`}
                      className="rounded-xl border border-white/10 bg-white/5 p-4"
                    >
                      <h3 className="text-[11px] uppercase tracking-[0.16em] text-light/50">
                        {metric.label}
                      </h3>
                      <p className="mt-2 text-sm sm:text-base font-semibold text-light">
                        {metric.value}
                      </p>
                      {metric.note ? (
                        <p className="mt-2 text-xs sm:text-sm text-light/65">
                          {metric.note}
                        </p>
                      ) : null}
                    </div>
                  ))}
                </div>
              ) : null}
            </article>
          ) : null}

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
            <article className={styles.card}>
              <h2 className={styles.cardTitle}>{t("caseStudies.sections.challenge")}</h2>
              <ul className={styles.list}>
                {challenge.map((item, idx) => (
                  <li key={`challenge-${idx}`}>{item}</li>
                ))}
              </ul>
            </article>

            <article className={styles.card}>
              <h2 className={styles.cardTitle}>{t("caseStudies.sections.delivered")}</h2>
              <ul className={styles.list}>
                {delivered.map((item, idx) => (
                  <li key={`delivered-${idx}`}>{item}</li>
                ))}
              </ul>
            </article>
          </div>

          <div className="mt-4 grid grid-cols-1 lg:grid-cols-2 gap-4">
            <article className={styles.card}>
              <h2 className={styles.cardTitle}>{t("caseStudies.sections.stack")}</h2>
              <ul className={styles.list}>
                {stack.map((item, idx) => (
                  <li key={`stack-${idx}`}>{item}</li>
                ))}
              </ul>
            </article>

            <article className={styles.card}>
              <h2 className={styles.cardTitle}>{t("caseStudies.sections.results")}</h2>
              <ul className={styles.list}>
                {results.map((item, idx) => (
                  <li key={`results-${idx}`}>{item}</li>
                ))}
              </ul>
            </article>
          </div>
        </div>
      </section>

      {/* INTERNAL LINKS */}
      <section className="pb-12">
        <div className={styles.container}>
          <div className={styles.card}>
            <h2 className={styles.cardTitle}>{t("caseStudies.sections.links")}</h2>
            <div className="mt-4 flex flex-wrap items-center justify-center gap-2">
              {primaryServicePath ? (
                <Link
                  to={primaryServicePath}
                  className="rounded-full border border-black/10 bg-purplesemilight px-4 py-2 text-sm text-dark/85 font-medium hover:bg-secondary hover:text-light"
                >
                  {t("caseStudies.links.relatedService", {
                    service: primaryServiceLabel,
                  })}
                </Link>
              ) : null}
              <Link
                to="/portfolio/"
                className="rounded-full border border-black/10 bg-purplesemilight px-4 py-2 text-sm text-dark/85 font-medium hover:bg-secondary hover:text-light"
              >
                {t("caseStudies.links.portfolioBack")}
              </Link>
              <Link
                to={buildContactIntentPath("similarProject")}
                className="rounded-full border border-black/10 bg-purplesemilight px-4 py-2 text-sm text-dark/85 font-medium hover:bg-secondary hover:text-light"
              >
                {t("caseStudies.links.contactSimilarProject")}
              </Link>
            </div>
          </div>
        </div>
      </section>
    </div>
  );
};

export default CaseStudyPreview;

const styles = {
  container: "mx-auto w-full max-w-6xl px-4 sm:px-6",
  card:
    "rounded-2xl border border-black/10 bg-primary/70 p-5 shadow-sm supports-[backdrop-filter]:bg-purplesemilight/40 supports-[backdrop-filter]:backdrop-blur text-light mb-5",
  cardTitle: "text-lg sm:text-xl font-semibold text-light/90",
  list: "mt-4 space-y-2 text-sm sm:text-base text-light/75",
  badge:
    "rounded-full border border-white/10 bg-white/10 px-3 py-1.5 text-sm text-light/85",
};
