import React, { useEffect } from "react";
import { graphql, type HeadFC, PageProps } from "gatsby";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import I18nHeadProvider from "../components/I18nHeadProvider";
import Layout from "../components/Layout";
import CaseStudyPreview from "../components/CaseStudyPreview";
import SEO from "../components/seo";
import type {
  I18nPageContext,
  LocaleQueryData,
} from "../components/I18nHeadProvider";
import data from "../data/data.json";
import images from "../images";
import type { Company } from "../interfaces";
import {
  buildBreadcrumbListSchema,
  buildCreativeWorkSchema,
  localizeSitePath,
} from "../utils/structuredData";

const info: Company = data[0];

const normalizeList = (input: unknown): string[] => {
  if (!Array.isArray(input)) return [];
  return input
    .map((item) => {
      if (typeof item === "string") return item;
      if (item && typeof item === "object" && "item" in item) {
        return String((item as { item?: string }).item || "").trim();
      }
      return "";
    })
    .filter(Boolean);
};

type CaseStudyPageContext = I18nPageContext & {
  slug: string;
};

function slugify(input: string) {
  return input
    .toLowerCase()
    .trim()
    .replace(/&/g, "and")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

const CaseStudyTemplate: React.FC<PageProps<unknown, CaseStudyPageContext>> = ({
  pageContext,
}) => {
  const slug = pageContext.slug;

  useEffect(() => {
    document.body.style.backgroundImage = `url(${images.bg.src})`;
    document.body.style.backgroundSize = "cover";
    document.body.style.backgroundPosition = "center";
    document.body.style.backgroundRepeat = "no-repeat";

    return () => {
      document.body.style.backgroundImage = "";
      document.body.style.backgroundSize = "";
      document.body.style.backgroundPosition = "";
      document.body.style.backgroundRepeat = "";
    };
  }, []);

  return (
    <Layout data={info}>
      <CaseStudyPreview slug={slug} />
    </Layout>
  );
};

export const Head: HeadFC<LocaleQueryData, CaseStudyPageContext> = ({
  data,
  pageContext,
}) => {
  return (
    <I18nHeadProvider data={data} pageContext={pageContext}>
      <CaseStudyHeadContent slug={pageContext.slug} />
    </I18nHeadProvider>
  );
};

const CaseStudyHeadContent: React.FC<{ slug: string }> = ({ slug }) => {
  const { t } = useTranslation();
  const { language, defaultLanguage } = useI18next();

  const name = t(`caseStudies.items.${slug}.name`, { defaultValue: "" }) as string;
  const description = t(`caseStudies.items.${slug}.summary`, {
    defaultValue: "",
  }) as string;
  const market = t(`caseStudies.items.${slug}.market`, {
    defaultValue: "",
  }) as string;
  const audience = t(`caseStudies.items.${slug}.audience`, {
    defaultValue: "",
  }) as string;
  const projectType = t(`caseStudies.items.${slug}.projectType`, {
    defaultValue: "",
  }) as string;

  const stack = t(`caseStudies.items.${slug}.stack`, {
    returnObjects: true,
    defaultValue: [],
  });

  const results = t(`caseStudies.items.${slug}.results`, {
    returnObjects: true,
    defaultValue: [],
  });

  const focus = t(`caseStudies.items.${slug}.focus`, {
    returnObjects: true,
    defaultValue: [],
  });

  const keywords = [
    ...normalizeList(stack),
    ...normalizeList(results),
    ...normalizeList(focus),
    market,
    audience,
    projectType,
  ]
    .map((entry) => entry.trim())
    .filter(Boolean);

  const localizedPath = localizeSitePath(
    `/portfolio/case-studies/${slug}/`,
    language,
    defaultLanguage
  );

  const liveProjectUrl = (info?.homePage?.portfolio || []).find(
    (project) => slugify(project.title) === slug
  )?.link;

  const breadcrumbSchema = buildBreadcrumbListSchema(info.url, [
    {
      name: t("menu.home") as string,
      path: localizeSitePath("/", language, defaultLanguage),
    },
    {
      name: t("menu.portfolio") as string,
      path: localizeSitePath("/portfolio/", language, defaultLanguage),
    },
    {
      name: name || slug,
      path: localizedPath,
    },
  ]);

  const creativeWorkSchema = buildCreativeWorkSchema({
    siteUrl: info.url,
    pagePath: localizedPath,
    name: name || `Case study: ${slug}`,
    description,
    inLanguage: language,
    aboutName: name || undefined,
    sourceUrl: liveProjectUrl,
    isPartOfPath: localizeSitePath("/portfolio/", language, defaultLanguage),
    keywords,
    audienceType: audience || undefined,
    genre: projectType || undefined,
  });

  const additionalSchemas = [breadcrumbSchema, creativeWorkSchema].filter(
    Boolean
  ) as object[];

  return (
    <SEO
      data={info}
      titleKey={`caseStudies.items.${slug}.metaTitle`}
      descriptionKey={`caseStudies.items.${slug}.metaDescription`}
      pathname={`/portfolio/case-studies/${slug}/`}
      schemaType="ProfessionalService"
      additionalSchemas={additionalSchemas.length ? additionalSchemas : undefined}
    />
  );
};

export default CaseStudyTemplate;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;
